window.HT_DAGGER = window.HT_DAGGER || {intro:{}, opp:[], kap:{}, app:{}};
HT_DAGGER.kap["5"] = {n:5, id:"k5", t:"Das Verwundete Reich", p:89,
 verse:[
  "Schönheit ist zerbrechlich. Ich blicke von meinem Balkon hoch oben in der Spire auf den Sonnenuntergang und sehe goldenes Feuer,",
  "das den Horizont leckt, Wolken, die sich wie ein Bluterguss purpurn färben. Der Smog der unteren Ebenen glüht in den letzten Strahlen,",
  "das langsame Absinken der Sonnenscheibe, die sich sammelnde Düsternis und das Versprechen einer helleren Morgenröte – und ich denke: All das ist ein Augenblick, der vergehen und niemals wiederkehren wird, seine einzigartigen Vollkommenheiten für immer verloren. Aber er lässt sich beständig machen. Das Auge eines Dichters, mit Kristall injiziert, damit der Anblick bewahrt bleibt von jemandem mit honigsüßer Zunge, der ihn beschreiben kann. Wir betreiben Hochöfen, die Smog in vollkommener Dichte ausstoßen, und galvanische Laternen, die die Sonnenscheibe nachbilden.",
  "Wir schmieden Zauber, um den Fluss der Zeit auf sich selbst zurückzubiegen.",
  "Im Streben nach Schönheit ergreifen wir die Sonne und nageln sie an den Himmel.",
  "Ich mag keine Sonnenuntergänge. Ich finde Schönheit in anderen Dingen.",
  "Was halte ich für schön? Eine geordnete Welt.",
  "— Aramos Brightness-Sears-The-Eye"],
 gar:[{n:11, x:"In manchen Fällen erschreckend wörtlich."}],
 legenden:null,
 ueberblick:[
  "Dieser Teil der Kampagne beschreibt die gefährliche Region jenseits der Wormery, im Kielwasser der Delving Machine. Es ist möglich – aber nur knapp –, dass die Delver die Maschine einholen. Wahrscheinlicher endet die erste Jagd der Delver auf die Maschine jedoch in einer Niederlage, und sie müssen sich in die Wormery zurückziehen, um sich neu zu sammeln."],
 inszenierung:[
  {t:"Zeichen und Vorzeichen", p:90, b:[
   "**Zeichen und Vorzeichen:** Während die Delver diese Region erkunden, stoßen sie auf Spuren der Delving Machine. Die Maschine dringt unaufhörlich tiefer ins Heart vor, aber da sie außerhalb der Zeit steht, folgt sie zugleich immer und immer wieder ihrem eigenen Weg zurück; Gegenwart faltet sich in Vergangenheit und Zukunft, bis sie im Kern zu einem einzigen zeitlosen Augenblick werden.",
   "Jede Landmarke in diesem Abschnitt hat einen Wake-Eintrag, der die Verwüstung beschreibt, die die Maschine hinterlassen hat. Mechanisch gilt: Betreten die Delver eine neue Landmarke in diesem Abschnitt, würfle einen W12. Bei 10–11 ist die Delving Machine vor Kurzem in der Nähe vorbeigezogen und hat womöglich schwere Schäden an der Landschaft angerichtet. Bei 12 ist sie gerade hier, entfernt sich aber. (Hast du außerdem noch nicht für alle Spielercharaktere Zenith-Vorzeichen eingestreut, dann betrachte einen Wurf von 1–2 als Anstoß, das hier nachzuholen.)"]},
  {t:"Die Jagd auf die Delving Machine", p:90, b:[
   "**Die Jagd auf die Delving Machine:** Mechanisch funktioniert die Delving Machine wie ein Delve, der parallel zu gewöhnlichen Delves abläuft. Die Maschine hat ihre eigene Resistenz, und Stress wird sowohl auf die Resistenz der Maschine als auch auf die des Delves angewendet. Senke die Resistenz der Delving Machine auf 0, und ihr habt sie eingeholt.",
   "*Beispiel:* Der ‚Delve‘ Jagd auf die Delving Machine hat derzeit eine Resistenz von 25, und der Delve zwischen den Grinding Halls und dem Hotel Amaranthine hat eine Resistenz von 10. Die Spielercharaktere bestehen eine Delve-Probe und fügen beiden Resistenzen W8 Stress zu; gewürfelt wird eine 6. Die Entfernung zum Hotel Amaranthine sinkt auf Resistenz 4, die Resistenz, um die Delving Machine einzuholen, auf 19.",
   "Verzögern sich die Verfolger, um sich zu heilen und zu rasten oder Ressourcen zu sammeln, werden sie von den Gefahren einer Landmarke aufgehalten, halten an, um einem Welpen zu helfen, oder Ähnliches, steigt die Resistenz der Delving Machine. Die erste Verzögerung erhöht die Resistenz um das Ergebnis eines W4, die nächste um einen W6, dann einen W8 und so weiter. Jenseits des W12 ist jede Hoffnung, die Delving Machine einzuholen, verloren – zumindest für diesen Versuch.",
   "Die Start-Resistenz hängt davon ab, wie die Charaktere vom aktuellen Aufenthaltsort der Maschine erfahren:",
   {t:"ul", x:[
    "**Gerücht:** 30. *Die Spieler folgen einem vagen Gerücht oder brechen einfach auf, um die Maschine zu suchen, ohne feste Anhaltspunkte.*",
    "**Frische Spuren ihres Durchzugs/magische Wahrsagung:** 25. *Entweder finden die Spieler eine Landmarke, die kürzlich von der Delving Machine verwüstet wurde, oder sie nutzen eine Fähigkeit oder eine andere Methode, um genaue Informationen über ihren aktuellen Aufenthaltsort zu gewinnen.*",
    "**Unerwartete Begegnung in der Wildnis:** 20. *Die Charaktere stoßen auf die Delving Machine, während sie unterwegs sind (vermutlich wenn sie bereits verwundet und erschöpft sind und wählen müssen, ob sie die Gelegenheit nutzen oder sich in Sicherheit zurückziehen).*"]},
   "Wenn es dramatisch passt – und das tut es meistens –, senkt heroische Selbstaufopferung durch eine Zenith-Fähigkeit die Resistenz um W12."]}],
 lm:[], delves:[], rest:[], dok:[]
};
(function(K){
K.lm.push(
{id:"lodernde-auge", t:"Das Blazing Eye", p:91, tiefe:3, dom:["Occult","Technology"], stress:"W8", haunts:[],
 text:[
  "**Wake:** Blitze grünen Lichts; Fetzen zerschossenen Metalls liegen über der Landschaft verstreut, während der Turm auf die Delving Machine feuert.",
  "Eine Landschaft aus zerschossenem Geröll unter einem rußverschmierten Himmel. Die Tunnel, die zum Rest des Heart führen, sind steilwandige Schluchten – um zwischen ihnen zu wechseln, müssen Reisende an die Oberfläche klettern und von Deckung zu Deckung huschen.",
  "Das einzige sichtbare Bauwerk in diesem Reich ist ein einzelner Turm auf einem Hügel. Ein abscheuliches Licht – grelle, grünliche Blitze statischer Entladung, die zwischen diesem grausamen Leuchtfeuer und den Wolken springen. Das Licht streicht über den Boden, angezogen von Bewegung – und alles, was davon erfasst wird, *verbrennt*. Wer auch immer diesen Turm erbaut hat, wollte ihn als Brandschneise gegen den Einfluss des Heart. Er sollte eine Linie ziehen, die besagt: *Dort liegt das Reich des brodelnden roten Chaos – und nicht einen Zoll weiter.* Offensichtlich ist das gescheitert, und nun steht der Turm im Zentrum einer öden Insel, umgeben von allen Seiten von brodelndem Chaos.",
  "Bei näherer Untersuchung ist der Turm eine Mischung aus grob behauenen Steinen, aufgeschichtet, um ein weit älteres Bauwerk zu stützen (vermutlich Prokatakos – und jedes Mal, wenn Delver ein uraltes Bauwerk entdecken, kommt irgendein Weiser angewackelt, streicht sich übers gelehrte Kinn und sagt: *„Hmm – vermutlich prokatakos.“*). Im Inneren herrscht ein Gewirr aus Drähten und Arkano-Technik – und ein stummer Titan aus zusammengenähten Körperteilen und mechanischen Komponenten. Dieser vier Meter große, massige Wächter ist der Hüter des Suchscheinwerfers oben und schätzt keine Einmischung.",
  "Es gibt Anzeichen, dass hier einst viele Menschen lebten – und sicher wäre dies ein bemerkenswert sicherer Haven, wären da nicht der ungastliche Titan und die Tatsache, dass das Licht jeden niederbrennt, der sich in der Nähe bewegt."],
 ressourcen:[
  "Klumpen gut durchgebratenen Fleisches (W6 Cursed, Verderblich)",
  "Geborgene Prokatakos-Verkabelung (W6 Technology)",
  "Gewaltige, das Heart versengende Lampe (W12 Technology oder Haven, Flüchtig, Sehr unhandlich, Schädlich)"],
 plots:[], regeln:null, unter:[],
 figuren:[
  {id:"stiller-titan", t:"Stiller Titan", p:91, text:["Wer hat ihn erschaffen? Was war sein Zweck? War er immer allein? Weder du noch ich werden jemals die Antworten auf diese Fragen erfahren."],
   namen:null,
   besch:"Langsame, bedächtige, fast rituelle Bewegungen, als hätte er gewusst, dass du kommst, und sich lange auf deine Ankunft vorbereitet; Gesichtszüge unter einem verhüllenden Umhang verborgen, doch Lichtblitze der Lampe enthüllen widersprüchliche Details – eine schuppige Hand, ein fast menschliches Gesicht, Metall, das durch Risse im Stoff ragt",
   motiv:"Lampe beschützen. Eindringling zerquetschen.", schw:"Riskant", res:"25", schutz:"2*",
   ressourcen:"Kunstvoll gravierte Knochen – Trophäen oder Erinnerungsstücke an jene, die an diesem Ort umkamen (W8 Wild)",
   ausr:"Gewaltige Faust (Kill W8, Brutal)",
   besonders:"Schutz 2 (10 gegen alles Cursed). Dem Licht auszuweichen erfordert eine **Evade+Technology**-Probe (**Riskant**, wenn man versucht, sich dem Turm zu nähern). Das Licht fügt W8 **Blood**-Stress zu, oder W12, wenn du die Domain **Cursed** oder irgendeinen **Echo**-Fallout hast.",
   dom:["Wild","Cursed"],
   fallout:[
    {t:"Burnt", r:"Blood", s:"leicht", x:"Alle brennbaren Gegenstände, die du bei dir trägst, entzünden sich. [Sofort]"},
    {t:"On Fire", r:"Blood", s:"schwer", x:"Würfle jede Runde einen W4. Bei 2–4 nimmst du entsprechend viel Stress auf **Fortune**, **Supplies** oder **Blood**, oder gibst einem anderen Spielercharakter den Fallout **Burnt**. Bei 1 wird dies gegen **Downed** getauscht. [Anhaltend]"}]}]},

{id:"grinding-halls", t:"Die Grinding Halls", p:92, tiefe:3, dom:["Warren","Technology"], stress:"W8", haunts:[],
 text:[
  "**Wake:** Die Delving Machine zieht durch einen Vermissian-Tunnel direkt unter den Grinding Halls hindurch. Das Rattern ihres Durchzugs verrät die Lage des verborgenen Tunnels.",
  "Die Grinding Halls sind schon lange hörbar, bevor ein Delver sie betritt. In diesen Hallen drehen sich endlos riesige Zahnräder, schwere Pendel schwingen, rätselhafte Getriebe greifen ineinander und ticken, während sie eine gewaltige Berechnung ausführen. Hier gibt es keinen festen Boden – jede Oberfläche ist Teil desselben großen Uhrwerks, auch wenn sich manche Räder langsamer drehen als andere. Wie ein vertracktes Rätsel ordnen sich die Hallen in neue Konfigurationen um, unsichtbare Scharniere und Achsen bewegen die Zahnräder in Position. Einen Weg durch dieses riesige lebende Uhrwerk zu finden, erfordert eine erfolgreiche **Delve+Technology**-Probe.",
  "Der langsamste – und damit sicherste – Teil der Hallen ist der untere Bereich nahe dem Aufzugsmechanismus. (Etwas dort unten im Schatten zieht die Uhr auf. Etwas Großes.) Je höher man in den Hallen klettert, desto komplexer und filigraner wird das Uhrwerk, anscheinend ohne Grenze. Schon wenige Ebenen höher sind die Zahnräder kleiner als ein Fingernagel und rotieren mit verschwimmender Geschwindigkeit, die Luft heiß und dick von Öl und Kupferspänen. Irgendwo im Dachboden der Hallen löst sich die Realität in vollkommene mathematische Ordnung auf, die Komplexität des Uhrwerks übersteigt die Grenzen grober, gemeiner Materie.",
  {t:"kasten", h:"Fallout: I Turned Into an Equation and Sublimed", b:["[Fortune, kritisch] Du kletterst zu weit und entdeckst, dass alles Zahlen ist und du dich asymptotisch der Null näherst. Du wirst für immer an der Schwelle zur Nichtexistenz existieren. Solange niemand einen W0 erfindet, bist du nicht direkt tot, aber funktional aus dem Spiel. [Sofort]"]},
  "Messingkrabben warten die Zahnräder und beseitigen alle Hindernisse. Einst gab es unzählige Schwärme dieser mechanischen Kreaturen, doch sie wurden für Ersatzteile abgeerntet, und nur eine Handvoll müder Krabben hält die Maschine noch instand.",
  "Bei gründlicher Suche in den Hallen entdecken die SCs Delving-Ausrüstung – Kompasse, ätherische Barometer, Pulskompasse –, die in die Zahnräder eingedrahtet ist. Das ist offensichtlich ein späterer Zusatz zu den Hallen, als hätte jemand versucht, diese große Maschine für eine andere Berechnung umzuwidmen. Eine erfolgreiche **Discern+Technology**-Probe lässt die Delver die wechselnden Gezeiten der Amyrran Zone in naher Zukunft genau vorhersagen; *Ablesungen aus den Grinding Halls* zählen als Ausrüstungsstück (Delve W10, aber bei jeder Verwendung sinkt die Würfelgröße um eine Stufe)."],
 ressourcen:[
  "Ablesungen aus den Grinding Halls (siehe oben)",
  "Geborgene Delving-Ausrüstung (Delve W8)",
  "Der zerbrochene Kadaver einer Messingkrabbe (W6 Technology)",
  "Verschnürte lebende Messingkrabbe, deren klägliche Beschwerden wir ignorieren (W8 Technology oder Haven, Mobil)",
  "Zahnräder und Altmetall (W6, Haven, Unhandlich)"],
 plots:[
  "**Die Expedition der Tower Division:** Beim Erkunden der Grinding Halls stoßen die Delver auf einen Schwarm Krabben, der unordentliche, faserige Stoff- und Fleischfetzen aus einem schnell rotierenden Satz Zahnräder zieht. Das ist alles, was von einem Forscher aus der Stadt Oben übrig ist. Ein weiteres Mitglied der Expedition steckt in einem nahen Teil der Hallen fest, der nur durch einen gefährlichen Spießrutenlauf aus Zahnrädern und Klingen erreichbar ist. Die Delver können einander über den Lärm des rotierenden Metalls hinweg Botschaften zurufen, aber tatsächlich zu dem eingeschlossenen Forscher zu gelangen, erfordert eine **Gefährliche Evade+Technology**-Probe, und ein Scheitern bedeutet … nun, wir verweisen auf die schon erwähnten unordentlichen, faserigen Fleischfetzen, die die Zahnräder verstopfen.\n\nAlternativ kann ein ausreichend stabiler Gegenstand die Zahnräder vorübergehend anhalten (würfle jedes Mal, wenn ein Charakter versucht durchzukommen, den dem Gegenstand zugeordneten Ressourcenwürfel; bei 4+ ist er sicher).\n\n**Fallout: Near Miss.** [Fortune, leicht] Du bist dem Tod von der Schippe gesprungen, und der Tod ist ein schlechter Verlierer. Wenn du das nächste Mal Stress nimmst, ist er **Brutal** (würfle den Stresswürfel zweimal und nimm den höheren Wert). [Sofort]\n\n**Fallout: Caught in the Gears.** [Blood, schwer] Als du dich aus den Zahnrädern befreist, bist du zerkaut und zermalmt. Du hast so viele Knochenbrüche und innere Blutungen, dass du nicht sagen kannst, wie schwer du verletzt bist. Solange du diese Folge hast, nimmst du jedes Mal, wenn du auf Fallout prüfst, mindestens leichten Fallout. [Anhaltend]\n\nDer einzige Überlebende ist **Parvedides Mammon**, ein menschlicher Zauberer (wobei *menschlich* hier womöglich Etikettenschwindel ist – er hat überlebt, indem er sich von Fleisch aus den Wänden ernährt hat, und steht kurz davor, zum Butcher zu werden (*Heart*, S. 188)). Er erklärt durch eine Reihe von Gebrüllen:\n- Er gehört zu einer Expedition aus der Stadt Oben – von der Tower Division der Akademie von Gwynn-Enforr. Man sieht es ihm vielleicht nicht an, da er zerlumpt, blutig, verdreckt und in einer wütenden Uhr eingeklemmt ist – aber er ist Akademiker.\n- Ursprünglich waren es sieben Mitglieder der Expedition. Zwei – Osiren und Lejan, die Drow-Diener – haben sich hier in den Grinding Halls verirrt. Diese verdammten Zahnräder bewegen sich. Nicht nur … schau, er weiß, dass sie rotieren, aber sie auch … die Wände … schau, sie sind weg.\n- Sie hatten einen Weg gefunden, die Zahnräder vorübergehend anzuhalten, indem sie sie mit Waffen verkeilten, aber das Schwert brach und teilte die Expedition. Egrin Weselsmith und Dr. Merelack blieben auf der anderen Seite zurück (derselben Seite wie die Spielercharaktere) und versprachen, Hilfe zu holen.\n- Eine weitere Zauberin, Heconia, ging voraus und kehrte nie zurück.\n- Es blieben also nur Parvedides und Kudel, und Kudel … nun, er hat es nicht geschafft. (Parvedides hat ihn ganz sicher nicht gegessen, und wie können Sie so etwas auch nur andeuten!? Es waren die geheimnisvollen weißen Schattenungeheuer aus den Wänden, die Kudel gefressen haben, und es ist reiner Zufall, dass die geheimnisvollen weißen Schattenungeheuer genau dasselbe Gebiss haben wie Parvedides.)\n\nWollen die Charaktere Parvedides retten, können sie entweder riskieren, den Zahnrädern auszuweichen, oder etwas finden, um sie zu verkeilen. Parvedides steht kurz vor der Mutation zum Butcher, und ohne eine erfolgreiche **Compel- oder Mend+Cursed**-Probe ist ihm der Geruch frischen Spielercharakter-Fleisches zu viel, und er versucht, die Charaktere zu fressen.\n\nParvedides’ Notizen zur Expedition der Tower Division sind eine W8-Occult-Ressource, aber wertvoller, wenn sie an Hesha Weselsmith oben in der Stadt Oben zurückgegeben werden (S. 9, S. 126)."],
 regeln:null, unter:[], figuren:[]},

{id:"red-litten-caves", t:"Die Red-Litten Caves", p:95, tiefe:3, dom:["Warren","Cursed"], stress:"W8",
 haunts:["*„Esst vom Fleisch und trinkt vom Blut“*, sagen die übertrieben freundlichen Cleaver (W10 Blood)","Die Gunst des Wounded King (W10 Fortune)"],
 text:[
  "**Wake:** Die Delving Machine zieht durch die Höhle des Wounded King. Sie verursacht außerdem einen gewaltigen Heartsblood-Ausbruch, der die unteren Kavernen flutet.",
  "Vielleicht war es der Durchzug der Delving Machine, der diese rote Hölle erschuf und das Heart so tief verwundete, dass sein lebendiges Blut aus dem Boden quoll. Oder dieser Ort ist älter, urtümlicher – eine Gabe des Heart an seine geliebten, hungrigen Kinder. Diese Red-Litten Caves sind ein Labyrinth aus Basalt, vulkanisch ausgespienen Lavaröhren und gewundenen Schorfhöhlen. Der Boden steht unter reinem Heartsblood. Heiße rote Flüssigkeit schießt aus Spalten in den Wänden oder quillt durch den Schlamm empor. Hier ist sie so rein, dass sie in rötlichem Licht glüht. An manchen Stellen fängt sie sogar Feuer, und Chaosflammen-Stöße explodieren durch die Tunnel. Das Heulen ferner Bestien hallt meilenweit, und es ist heiß genug, einen Vermissian Knight in seiner Rüstung zu backen.",
  "Es gibt hier auch Hexen – man findet sie in den größeren Kavernen, schwebend über Becken aus blubberndem Heartsblood, während psychische Fruchtblasen um sie gerinnen, in denen sie ihre künftigen Gestalten gebären. Besser, man stört sie nicht.",
  "Dieser Ort ist nicht sicher. Dieser Ort ist der perfekte Gegenpol von ‚sicher‘. Wütende Heartsblood-Bestien, kannibalische Cleaver-Stämme, das stete Risiko von Explosion oder Überflutung – und allein die Heart-Strahlung in der Luft genügt, um den sanftesten Bibliothekar aus der oberen Spire in einen heulenden, blutverschmierten, nackten Kultisten zu verwandeln, der seine eigene keimende Göttlichkeit anbetet.",
  "Trotzdem gibt es reichlich Besucher in diesen Red-Litten Caves. Reines Heartsblood ist als Handelsware oder alchemistische Zutat wertvoll. Die äußeren Litten Caves sind übersät mit den zersplitterten Resten von Bohrtürmen, Pumpen und Rohren – Zeugnisse von Versuchen, das Heartsblood abzuzapfen. Heutzutage sind die Methoden bescheidener. Hier ist ein Metallfass: Füll es auf, lass dich nicht fressen, und kriege nicht zu viel von dem roten Zeug auf die Haut.",
  "**Der Wounded King:** Im Zentrum des Labyrinths liegt der Thronsaal des Wounded King, eines Geschöpfs des Heart. Der König – oder zumindest eine Hälfte von ihm – war einst ein Drow-Mechaniker, Mitglied der Besatzung der Delving Machine auf ihrer unglückseligen Jungfernfahrt. Unter dem Blut sind noch die Fetzen einer Vermissian-Ingenieursuniform zu erkennen (sein Abzeichen trägt die Nummer #4549). Dieser unglückliche Mechaniker fiel von der Delving Machine und wurde in zwei Hälften geschnitten, als sie über ihn hinwegrollte.",
  "Das Heart ließ ihn nicht sterben. So ist die rechte Hälfte des Wounded King die eines Drow-Mechanikers. Die linke Hälfte ist nicht da – oder vielmehr ist sie ein sich ständig wandelndes rotes Gewirr aus Tentakeln und fadenziehenden Klumpen gerinnenden Bluts, das die sterbliche Hälfte des Königs mit dem lebenden Heart verbindet. Was auch immer von dem namenlosen Mechaniker übrig ist, wurde vollständig von seiner neuen Rolle als Quasi-Avatar des Heart aufgesogen. Hexen kommen auf der Suche nach Prophezeiungen hierher; Cleaver bringen ihm erlesene Fleischbrocken. Das richtige Opfer kann den König zum Sprechen bewegen. Seine ‚Visionen‘ sind stets er selbst, der in der ersten Person die Erfahrungen der dem Gegenstand der Wahrsagung nächsten, mit dem Heart verbundenen Wesenheit beschreibt. Fragen die Spielercharaktere ihn also, wie sie die Delving Machine finden, beschreibt er etwa die Sicht einer Heartsblood-Bestie auf die Maschine, wie sie vorbeidonnert. Es stecken nützliche Informationen darin, aber sie müssen aus der Perspektive des Beobachters herausgelöst werden. (Beunruhigenderweise kann der König Visionen über die Stadt Oben haben, was nahelegt, dass jeder und alles in der Spire zumindest ein wenig vom Heart berührt ist.)",
  "**Besondere Regeln:** Jede Stunde, die in den Red-Litten Caves verbracht wird, verursacht den Delvern W4 **Echo**-Stress. Tiefere Höhlen, Heartsblood-Ausbrüche und Ähnliches bedeuten deutlich höhere Stresswerte (bis zu W12 Brutal in den tiefsten Höhlen)."],
 ressourcen:[
  "Heartsblood, leuchtend und dampfend (W10 Cursed, Schädlich, Tabu)",
  "Mit urtümlichen Runen gezeichnete Steine (W8 Warren, Leuchtfeuer)"],
 plots:[
  "Zwei Gruppen von Plünderern ernten Heartsblood aus den Red-Litten Caves; beide verkaufen das rohe Heartsblood an Hexen und Alchemisten (Ptolemy Bay kauft von beiden). Bergleute der **Craste Mining and Alchemy Company** lagern in den äußeren Höhlen, auch wenn sie Probleme damit haben, dass ihre Arbeiter zu randalierenden Chaosungeheuern mutieren. Der Lageraufseher, **Vollus**, hat beschlossen, dass Vorsicht die bessere Hälfte der Tapferkeit ist, und braucht nur tapfere Karawanenwächter, die ihn und seinen Heartsblood-Vorrat zurück nach Derelictus eskortieren. (Viel leicht gebrauchte Ausrüstung, W10 Warren.) Die anderen Bergleute sind Plünderer aus der Wormery, angestellt von Light-Falls-The-Leaf (S. 83). Delver finden leicht Arbeit beim Heartsblood-Ernten für sie (Kost und Logis, W6 Haven – und sie übernimmt die obligatorische Entfernung von W4 **Echo** an den Toren der Wormery).",
  "Verbinde die Abzeichennummer des Königs mit den Aufzeichnungen im Haus von Aramos Brightness-Sears-The-Eye, um den Drow als **Galec Snare** zu identifizieren. Seine Tochter Medel lebt noch in der Stadt Oben – ihre Familie verlor alles, als das OCM das Vermissian-Projekt einstellte, und nun gehört sie zur Gemeinde der Hungrigen Tiefe in Derelictus (S. 121). Wird Medel zu ihrem Vater gebracht, gewinnt man eine Gunst des Königs."],
 regeln:null, unter:[], figuren:[]},

{id:"castle-of-skin", t:"Die Castle of Skin", p:96, tiefe:3, dom:["Desolate","jede beliebige weitere"], stress:"W8",
 haunts:["Keine, technisch gesehen. Aber praktisch jeder Fallout lässt sich hier entfernen"],
 text:[
  "**Wake:** Die Delving Machine reißt durch die untere Ebene der Burg – und verursacht entsprechende Stigmata bei dem Bonded.",
  "Diese Landmarke ist ein wenig ein Gimmick – die Gruppe landet ‚im Inneren‘ eines der Spielercharaktere. Die Burg ist eine Spiegelung/alternative Perspektive/ein Gedächtnispalast eines Charakters, den wir als den Bonded bezeichnen. Jeder der Charaktere kann der Bonded sein – wähle jemanden, dessen Geschichte von etwas Betrachtung profitieren würde oder der schon eine Weile nicht im Rampenlicht stand. (Kehren die Charaktere später zu dieser Landmarke zurück, wähle einen anderen Bonded oder mache die Rückkehr schlicht unmöglich.)",
  "Zustand und Einrichtung der Burg spiegeln also das Wesen des Bonded. Ist der Bonded ein alter Vermissian Knight, dann ist sie eine bröckelnde, verstaubte alte Feste mit vielen Steampunk-Apparaturen und Ölgemälden mächtiger Lokomotiven auf Questen. Ist der Bonded ein junger Cleaver, voller Saft und Kraft und beunruhigenderer, unnatürlicherer Flüssigkeiten, dann ist die Burg eher … nun ja, stachelig-fleischig, mit Gewölbedecken aus Knochen und roten Kellern, aus denen tropft, was hoffentlich Wein ist.",
  "In der Burg können Schemen aus der Vergangenheit des Bonded hausen. Sie haben keine Namen und nennen einander mit recht allgemeinen Titeln (die Köchin, der Astrologe, der Priester und so weiter).",
  "Zu beachten:",
  {t:"ul", x:[
   "Hat der Bonded-Charakter anhaltenden Fallout oder ähnliche Zustände, manifestiert sich das in der Burg als Ungeheuer oder anderes Problem. Hat der Bonded zum Beispiel den Fallout **Ravening Beast**, belagert eine Ravening Beast die Burg. Hat der Charakter den Fallout **No Rations**, wurde der Schlüssel zur Vorratskammer gestohlen, und alle in der Burg zeigen mit dem Finger aufeinander. (Dies ist ein hervorragender Ort, um Amyrran-bezogenen Fallout wie **Marked by the Amyrran** ins Rampenlicht zu rücken, der sich als wuchernder Pilz oder als Angriff von Streitkräften der Opposition manifestieren könnte.)",
   "Baue Verweise auf die Geschichte des Bonded in die Beschreibung der Einrichtung ein. Bücher in der Bibliothek, Statuen in der Kapelle und Wasserspeier auf den Dächern können alle mit Hintergrundgeschichte gefärbt sein.",
   "Wird die Burg beschädigt, spiegelt sich dieser Schaden im Bonded-Charakter. Zerbrich ein Fenster, bekomm Kopfschmerzen. Verbrenn ein Buch, verlier eine Erinnerung. Reiß die Burg nieder, zerfließ zu schleimigem, knochenlosem Protoplasma. Wie innen, so außen."]},
  "Die Delver befinden sich in der Burg, ohne sie betreten zu haben – ein Höhlengang geht in einen Korridor der Feste über, oder sie treten aus einem staubigen Tunnel in die Keller. Sie bemerken erst, dass sie in einer Burg sind, wenn sie aus einem Fenster schauen.",
  "Enthülle nicht, was vor sich geht, bis einer der Charaktere den Zusammenhang erkennt. Danach beziehe den Bonded in die Ausgestaltung ¹¹ des Rests der Burg und ihrer Bewohner ein. Zu entdecken, dass man sich im Inneren seiner selbst befindet, ist mindestens W4 **Mind**-Stress wert."],
 ressourcen:[
  "So ziemlich alles, aber es gibt einen Haken. Die Charaktere können in der Burg etwas Nützliches finden, aber es mitzunehmen verursacht Brutalen **Fortune**-Stress in Höhe des Ressourcenwerts. Brauchen die Delver also dringend ‚ein paar Münzen von geringem Wert‘ (W4 Haven), erleidet der Bonded W4 Brutalen **Fortune**-Stress – (der Bonded würfelt 2W4 und wählt den höheren Wert für seinen Stress)."],
 plots:[
  "Hat der Bonded offensichtlich einen unangenehmen Brocken anhaltenden Fallouts, ist dies der Ort, ihn loszuwerden.",
  "Die Opposition könnte diese Burg zuerst entdecken und einen Marionettenherrscher einsetzen, der es ihr erlaubt, den Bonded-Charakter in der Außenwelt zu beeinflussen."],
 regeln:null, unter:[], figuren:[]}
);
K.delves.push(
{id:"d-lodernde-auge-grinding-halls", t:"Das Blazing Eye zu den Grinding Halls", p:92, von:"lodernde-auge", nach:"grinding-halls", tiefe:3, dom:"Technology", stress:"W8", res:14,
 besch:"Gräben und Tunnel, versengt von Energiebeschuss; Verbrannte Skelette von Dingen, die niemals hätten leben dürfen; Höhlen, die kaum eng genug sind, um sich hindurchzuquetschen; Der Geruch verbrannten Fleisches, der in den von verbranntem Metall und Kupferspänen übergeht; Das donnernde Läuten einer fernen Uhr.",
 erg:[
  "Das Licht jagt durch den Korridor. Es sind nur W6 **Blood**-Stress – aber man kann sich nirgends verstecken.",
  "Eine Drow namens Pearl stolpert durch den Korridor. Sie ist mit einem Flensling (S. 84) infiziert und wurde der Zutritt zur Wormery verweigert. Sie kann Avallone (S. 78) nicht finden und glaubt deshalb, ihre einzige Hoffnung sei, den Parasiten auszubrennen.",
  "Imps, die das Angry Light anbeten, suchen Opfergaben. Handle ihnen **Cursed**-Waren gegen Durchlass ein, sonst suchen sie lebende Opfergaben.",
  "Uhrwerk-Plünderer, bewaffnet mit geschärften Zahnrädern, stehlen Teile der Grinding Halls als Altmetall.",
  "Die Geister jahrtausendetoter Ingenieure heulen verzweifelt über den Zustand ihres Meisterwerks – und lassen ihre Frustration womöglich an vorbeikommenden Reisenden aus.",
  "Ein Tunneleber, behängt mit Zahnrädern und Rädchen als bizarrer Rüstung, flieht durch den Tunnel, verfolgt von Jägern. Es ist die heilige Jagd auf den Machine Boar, eine Tradition, die bis in unvordenkliche Zeiten zurückreicht. Die Jäger tragen rituelle Gewandung, die seltsam an die Ausrüstung der Spielercharaktere erinnert."],
 verb:"Repariere die Verbindung zwischen Uhr und Turm, und die Route ist gesichert. (Die Geschäftsführung übernimmt keinerlei Verantwortung für die Folgen, wenn man ein geheimnisvolles Okkult-Laser-Leuchtfeuer an eine ebenso geheimnisvolle technomagische Uhr anschließt, schon gar nicht, wenn die Uhr für ihre höheren Berechnungen Laserlichtpulse brauchte, um sich von träger Materie zu befreien.)",
 express:false},
{id:"d-wormery-red-litten-caves", t:"Wormery zu den Red-Litten Caves", p:94, von:"wormery", nach:"red-litten-caves", tiefe:3, dom:"Warren", stress:"W8", res:12,
 besch:"Ein langsamer Abstieg durch schlammige Schluchten und Rinnen; Blutige Fumarolen speien schwefligen Rauch und Brocken gekauten Fleisches; Fremdartige Schlammebenen erstrecken sich meilenweit unter einem rötlichen Himmel, und aus den Gedanken und unbewussten Wünschen der Delver geborene Gestalten blubbern empor und zerfallen wieder, zu schwach zum Überleben.",
 erg:[
  "Vom Heart gefärbte Lava überflutet die Route. Sie wird von euren Wünschen geformt und will bei euch sein.",
  "Bergleute überqueren die Ebenen auf Stelzen und tragen vorsichtig eine kostbare Fracht Heartsblood über den Morast. Hoppla.",
  "Wallender roter Nebel verstopft eure Lungen, versengt Schleimhäute und zersetzt eure Seelen. Schnell Schutz suchen!",
  "Ein Hexenschrein, gebaut aus dem noch lebenden Kadaver des letzten Eindringlings, versperrt den Weg – wer ihn ohne Erlaubnis passiert, riskiert, dessen Platz einzunehmen.",
  "Heartsbeasts streifen durch die Tunnel, ihre Reißzahn-Rachen brüllen zum Lob des Wounded King.",
  "Drei uralte Hexen erscheinen den Spielercharakteren und prophezeien. Sie werden keine Ruhe finden, bis die Weiße Königin den Roten König ehelicht, sie werden Verderben über die Stadt Oben bringen, sie werden die in Feuer und Wasser geschriebene Wahrheit finden."],
 verb:"Gewinne die Gunst des Wounded King, und er wird den Pfad zu seiner Burg begradigen.", express:false},
{id:"d-castle-of-skin-aetherstorm", t:"Die Castle of Skin zum Aetherstorm", p:97, von:"castle-of-skin", nach:"aetherstorm", tiefe:3, dom:"Wild", stress:"W8", res:12,
 besch:"Die Ziergärten und Waldparks der Burg werden von einem anwachsenden Sturm zu Splittern zerblasen; Tunnel ächzen und bersten und brechen in schwebende Felsbrocken; Der Bonded krampft, und sein Körper explodiert zu einer fleischigen Tür zum Aetherstorm (sie finden den Bonded-Charakter auf der anderen Seite, oder zumindest jemanden, der ihm genug ähnelt und genug wie er denkt, um denselben Charakterbogen zu haben).",
 erg:[
  "Kindheitsfreunde des Bonded kauern sich vor dem Sturm zusammen, der sie verschlingen wird.",
  "Blitzspeere treffen unvorsichtige Reisende.",
  "Eine von Castamir (S. 100) gebaute Flugmaschine stürzt in der Nähe ab und tötet den Piloten beim Aufprall.",
  "Der Sturm schlägt einen Geschützturm oder Turm aus der Burg, der in den Himmel davonschwebt. Wie lange hält seine Levitationsmagie? Finden wir es gemeinsam heraus.",
  "Eine Stimme spricht im Donner – wähle den Gott oder Geist, der am engsten mit einem Spielercharakter verbunden ist.",
  "Spiegelbilder der tiefsten Ängste der Bonded-Charaktere patrouillieren durch die Tunnel."],
 verb:"Der Bonded-Charakter kann freiwillig W8 **Fortune**-Stress nehmen, um die Verbindung zu stärken.", express:false}
);
})(HT_DAGGER.kap["5"]);
(function(K){
K.lm.push(
{id:"arch-gwynn-ardasi", t:"Der Arch of Gwynn-Ardasi", p:98, tiefe:3, dom:["Technology","Cursed"], stress:"W8", haunts:[],
 text:[
  "**Wake:** Keine. Die Delving Machine kommt nicht hier entlang.",
  "Die Delver stoßen auf eine unwahrscheinliche Eisenbahnlinie, die mit dem übrigen Vermissian-Netz nicht verbunden ist. Die Linie windet sich durch Gänge, denen kein Zug jemals folgen könnte – vielleicht verläuft sie entlang eines schmalen Felsgrats oder schlängelt sich durch enge Kavernen. Unerbittlich führt sie zu einem titanischen Steinbogen, umwickelt mit Kabeln und behängt mit arkanen Geräten. (Er ähnelt sehr dem Nameless Summer Country, S. 40 – aber wo jenes verlassen und melancholisch war, wirkt dieser noch aktiv und … zornig.) Jenseits des Bogens liegt brodelndes rotes Chaos; das Gelände – einschließlich des Bogens selbst – löst sich in das urtümliche Heart auf. Strömungen fließen und winden sich in diesem Chaos, Energieflüsse, kartiert und geformt von der Maschinerie.",
  "So sieht ‚*wir haben einen Gott ausbluten lassen, um unsere magische Modelleisenbahn anzutreiben*‘ aus. Einst gab es mehrere solcher Bögen, doch die anderen wurden vom Heart aufgesogen. Sie funktionieren noch, verbinden die Stadt Oben noch immer mit dem Chaos darunter, auch wenn sie verschlungen und in neuen Formen neu geschaffen wurden.",
  "Stellwerk-Kultisten und andere Anhänger der Vermissian kommen hierher, um diese Ikone anzubeten. Sie bringen Opfer dar und schleudern unglückliche Opfer in den Bogen. Gefangene Delver werden womöglich zur Vollendung hierher gebracht.",
  "Allerdings – Dinge, die in den Bogen geworfen werden, sind vielleicht nicht vernichtet. Es besteht die Chance, dass alles, was in den Bogen geschleudert wird, entlang der Schienen teleportiert wird und irgendwo anders im Vermissian-Netz landet. In den Bogen zu treten bedeutet, W12 **Echo**-Stress zu nehmen und sein Schicksal in die Hände der Spielleitung zu legen.",
  "Von diesem Punkt aus gibt es keine weiterführenden Routen. Es ist eine Sackgasse."],
 ressourcen:[
  "Verrottende Arkano-Technik (W10 Technology, Verderblich)",
  "Pilgermarken und Opfergaben (W6 Religion, Nische)"],
 plots:[
  "Der Vermissian Knight **Otho Caern** war vor langer, langer Zeit einmal Mitglied des OCM. Vor vielen vergessenen Lebzeiten stieg er in die Stadt Unten hinab, um ein Stromkabel eines stillgelegten Stellwerks abzutrennen. Es sollte eine schnelle Reparatur sein, aber er folgt diesem Kabel nun seit Jahrzehnten. Jetzt ist er ein alter Vermissian Knight, verformt und zerschlagen von seinen Abenteuern in diesem Labyrinth. Er kann sich nicht mehr erinnern, was der Zweck seiner Queste war (er muss gewaltig gewesen sein) oder wer er in der Stadt Oben war (er erinnert sich auch nicht an Sonnenlicht oder den Geschmack von Regen), aber er ist entschlossen, dem Kabel bis zum Ende zu folgen. Er braucht die Hilfe der Spielercharaktere, um dorthin zu gelangen. Als Belohnung bietet er einen Schatz an, den er unzählige Jahre mit sich getragen hat – seinen OCM-Mitarbeiterausweis, der den Standort des OCM-Büros in der Stadt Oben verrät (S. 123).",
  "Eine genaue Untersuchung (**Discern+Technology**) des Bogens zeigt, dass er nicht nur mit verschiedenen Sensoren und Messgeräten verbunden ist, die die Strömungen des Heart messen – es gibt auch eine Steuerleitung, die sich einen Tunnel entlangschlängelt. Ihr zu folgen führt schließlich zum Vermissian Operations Centre (S. 102)."],
 regeln:null, unter:[], figuren:[]},

{id:"aetherstorm", t:"Der Aetherstorm", p:100, tiefe:3, dom:["Wild","Occult"], stress:"W8", haunts:["Das Witchhouse (siehe unten)"],
 text:[
  "**Wake:** Die Delving Machine hat diesen Abgrund aufgerissen.",
  "Wenn sie hier ist, überlappen sich Vergangenheit und Gegenwart, sodass sie anscheinend durch Stein reißt, der vor ihr auftaucht und in ihrem Kielwasser verschwindet. Gewandte Charaktere könnten den Abgrund womöglich überqueren, indem sie der Maschine folgen und im zeitgefalteten Bereich bleiben.",
  "Hier weichen Tunnel und Gänge einer großen Leere. Gewitterwolken wirbeln umher und blitzen in scharlachrotem Licht. Verdrehte Dinge, die weniger wie Vögel aussehen und mehr wie Klumpen zerrissenen Fleisches, schweben in blutigem Schwarm durch den Himmel. Felsbrocken taumeln durch die Luft und trotzen der Schwerkraft. Der Aetherstorm sieht aus wie Chaos – aber eher so, als hätte jemand mit einem Vorschlaghammer auf ein zartes Planetarium eingeschlagen. Manchmal brodelt *Bedeutung* aus dem Chaos empor, und die Anordnung schwebender Inseln, beleuchtet von knisternden ätherischen Entladungen, gleicht perfekt einem arkanen Sigil oder dem Gesicht eines Gottes.",
  "Den Aetherstorm ohne Fortbewegungsmittel zu überqueren ist gefährlich. Ein fliegendes Schiff oder ein Zauber hilft, ebenso etwa ein Seitenschritt durch das Grey oder das Zwingen der flatternden Fleischdinger, Reisende hinüberzutragen. Andernfalls: viel Spaß beim Springen von Fels zu Fels (**Delve+Wild**, und **Riskant**).",
  "Hier schwappt viel ätherische Hintergrundenergie umher, und Magie zu wirken fällt leicht: Sie steigert die Wirksamkeit aller hier gewirkten Zauber um eine Würfelstufe. Macht zieht Zauberer an wie Fliegen (lästige, widerwärtige persönliche Angewohnheiten, unverständliches Summen – passt), und viele der schwebenden Felsen sind oder waren von arkanen Eremiten bewohnt. Dazu gehören:",
  "**Heresh Spellfule:** Oder vielmehr sein leerer Trödelladen. Dieses leicht angesengte Geschäft war einst Teil von Derelictus (siehe Coinpit, S. 30), bis Spellfule eine geheimnisvolle Schriftrolle erwarb, die seinen Laden viele Ebenen tief ins Heart hinabzog. Er ist hier gelandet, prekär auf einem schwebenden Felsen über einem Abgrund balancierend. Von Spellfule keine Spur (vielleicht ist er weiter unten), aber eine Durchsuchung des verlassenen Trödelladens fördert magere Vorräte zutage – und ein schweres eisernes Schriftrollenbehältnis, mit Wachs versiegelt. Wird die Schriftrolle geöffnet, zieht sie die aktuelle Umgebung des Öffnenden eine Tiefe tiefer ins Heart hinab (sie in einer Landmarke der Tiefe 4 zu öffnen ist … unklug), mit dem begleitenden Chaos und der Zerstörung. Jeder in der Landmarke nimmt W12 Stress (**Blood**, **Fortune** oder **Echo**). Das Schriftrollenbehältnis zu öffnen ist eine sehr schlechte Idee. Jemand anderen dazu zu bringen, es zu öffnen, während man sich in sicherem Abstand befindet, ist viel besser.",
  "**Die Junk Mages Ulder und Rekom:** Zwei Brüder, die kamen, um den Aetherstorm zu studieren, sich aber über ihre Deutungen entzweiten. Ulder, der nun oben auf ihrem schwebenden Felsen lebt, vertritt, die Blitze seien die aufblitzenden Gedanken des Red King, und wer zum Sprachrohr Seines göttlichen Begehrens werde, könne kosmische Erkenntnis erlangen. Rekom, der nun in einer primitiven, an die Unterseite des Felsens geschnallten Hütte lauert, argumentiert, die schwebenden Felsen der Region seien Fragmente des Stone Chorus, und dieser Ort sei im Grunde ein heiliges Puzzle von unvorstellbarer Komplexität. So rennt der eine wild herum und tut, was ihm die Blitze zu tun befehlen, und der andere betreibt außergewöhnlich filigrane Rekonstruktionsarbeit mit sehr langen Pinzetten.",
  "**Castamir der Strahlende:** Castamir behauptet, ein pensionierter Priester von Luxulyan zu sein, dem Duke of Air – einer Gottheit der Flugmaschinen. Sein kleines Häuschen ist jedenfalls vollgestopft mit Modellen, Prototypen und Ersatzteilen für solche Maschinen, aber Castamir erklärt, er sei zu alt, um auf zerbrechlichen Flügeln herumzuflattern, und er sei nun Anhänger eines Gottes, den er hier unten entdeckt hat, Bonboh, Herr der guten Tasse Tee und des Hinsetzens. Die Delver dürfen gern seine alten Flugmaschinen nehmen, falls sie den Abgrund überqueren müssen. Tatsächlich ist Castamir ein Anbeter der Hungrigen Tiefe, und seine Maschinen sind so gebaut, dass sie auf halbem Weg über den Aetherstorm versagen.",
  "**Champion of Our Lady of Vengeance:** Die Bewohnerin dieses schwebenden Unterschlupfs ist eine mächtige Drow-Zauberin, **Nahaer**, die geschworen hat, die Aelfir zu stürzen und die Stadt Oben mit der gewaltigen Magie zu befreien, die sie hier unten gemeistert hat. Leider hat sie so lange gezögert, dass sie die Amyrran Zone nicht mehr verlassen kann, sodass ihr Plan, die Stadt Oben mit teuflischen Flüchen auseinanderzureißen, niemals Früchte tragen wird. Spielercharaktere, die ihr messianisches Gefasel aushalten, können Zugang zu ihrem umfassenden (wenn auch veralteten) Wissen über Aelfir-Politik und -Genealogien erhalten, das detaillierte Informationen über Aramos Brightness-Sears-The-Eye (S. 14) enthält.",
  "**Lostlight Observatory:** Ein verlassenes Observatorium – verlassen, als die Zauberer eine bestimmte Konfiguration des Aetherstorm sahen, die ihre Köpfe zu Asche verbrannte. Ihre aufgebrachten Geister spuken noch dort, verstellen boshaft Fokussierknöpfe und stoßen Teleskope aus der Ausrichtung. Dennoch können ihre Beobachtungen nützliche Informationen über den Pfad der Delving Machine liefern (Delve W10, Einmalig).",
  "**Das Witchhouse:** Früher das Häuschen einer Hexe – sie wurde von Dieben erschlagen, und ihr Blut sickerte ins Haus und ergriff Besitz davon. Das Witchhouse hungert nun nach Fleisch und manipuliert seine Einrichtung, um Opfer in den Ofen/Mund zu treiben. Es mag jedoch andere Hexen und höfliche Gäste recht gern und bietet einen Ruheplatz (Haunt: W8 Fortune oder Supplies), wenn sie ihm zuerst jemanden zu fressen geben."],
 ressourcen:[
  "Echter schwebender Fels (W6 Wild, Mobil)",
  "Abgefüllter Aetherblitz (W8 Occult, Flüchtig)"],
 plots:[
  "**Sweathboth der Fährmann** rudert sein schwebendes Ruderboot zwischen den Inseln und liefert Vorräte an die verschiedenen Arkanisten. Berüchtigt wortkarg, will er nicht darüber sprechen (und scheint nicht zu bemerken), dass sein Boot schwebt. Er kann Reisende über den Sturm bringen, aber nur, wenn sie zuvor ein paar Besorgungen für ihn erledigen – etwa den ganzen Weg bis Wormsea zu wandern, um Vorräte an Wurmfleisch zu holen."],
 regeln:null, unter:[], figuren:[]},

{id:"vermissian-operations-centre", t:"Das Vermissian Operations Centre", p:102, tiefe:3, dom:["Technology","Cursed"], stress:"W10", haunts:[],
 text:[
  "**Wake:** Der Durchzug der Delving Machine lässt die Überwachungstafeln hier aufleuchten und macht deutlich, dass dieser Ort mit der Maschine verbunden ist. Die Maschine rattert durch einen Tunnel unter dem Centre.",
  "Die Aufzeichnungen des Vermissian-Projekts sind lückenhaft und verworren. Wahrscheinlich ist die einzige lebende Seele, die weiß, ob dieser Ort gebaut wurde oder nicht, Aramos Brightness-Sears-The-Eye. Aber ob er von Sterblichen errichtet wurde oder dem fruchtbaren, traumgeformten Fleisch des Heart entsprang – er ist jetzt hier.",
  "In den ursprünglichen Plänen für die Vermissian war dieser Ort das Nervenzentrum des gesamten Netzes. Klackernde Tafeln und blinkende Lichter verfolgten den Fortschritt der Züge, während sie nach präzisen Fahrplänen durch den verdrehten Unraum glitten.",
  "Arkane Mechanismen flüsterten Stellwerken und ätherischen Schornsteinen zu und regelten den Energiefluss aus dem Heart. Es war ein Monument der Ordnung, der Arkano-Technik, der vollkommenen Vision der Aelfir.",
  "Jetzt ist es die Hölle. Verdrehtes Metall wuchert wie ein Krebsgeschwür. Monitore speien das grelle Licht der Leere. Arkane Maschinen heulen vor Qual, jede Anzeige und jedes Messgerät so weit in den roten Bereich gedrückt, dass sie bluten. Rohre speien giftige Gase und fettige Asche; die Sicht ist praktisch null. Alles ist beunruhigend flüssig und doch zugleich bösartig dornig.",
  "Einschließlich der Kreaturen, die hier leben. Das Heart antwortete auf ihre Wünsche und verformte sie im Sekundenbruchteil des Vermissian-Zwischenfalls gemäß ihren flüchtigen Gedanken. Drow-Operateure mit grotesk vergrößerten Augapfel-Trauben überwachen Reihen von Bildschirmen, ihre verkümmerten Körper kaum imstande, ihre vielfingrigen Hände zu den Steuerungen zu heben. Menschliche Arkano-Techniker flackern in und aus der Existenz, Zauber brechen durch die dünne Materie ihrer Schädel.",
  "Am schlimmsten sind die armen Teufel, die sahen, was kam, und zu fliehen versuchten. Das Heart verwandelte sie in Wesen, die die heranrollende Welle aus Chaosmagie überleben konnten. Sie sind noch immer da drin und warten darauf, dass ein Eindringling von der Oberfläche eintrifft, damit sie sein Gesicht stehlen und in die Stadt Oben zurückkehren können.",
  "In Spielbegriffen: *Alles*, was man hier drin tut, riskiert W10 **Echo**-Stress."],
 ressourcen:["Heart-durchtränkter Retro-Tech-Schrott (W10 Technology oder Cursed, Schädlich)"],
 plots:[],
 unter:[{t:"Warum sollte jemand ins Cronenberg-trifft-Tschernobyl-Land reisen:", b:[{t:"ul", x:[
  "Die mit diesem Ort verbundenen Instrumente sind längst fort, vom Heart verschlungen oder haben nie existiert, aber sie liefern trotzdem Messwerte – und können den Aufenthaltsort der Delving Machine zeigen. Die Maschinerie kann außerdem die Stellwerke der verschiedenen Linien steuern, was genutzt werden kann, um den Fluss der Magie umzuleiten (genau wie es Tython Ardasi vorgeführt hat), und senkt die Resistenz einer Jagd auf die Delving Machine um W8. Schließt man es an Morveren Trake in White Station (S. 66) an, wird das zu W12 aufgewertet.",
  "Theoretisch könnte man von hier aus den Verrücktheitsgrad der gesamten Vermissian-Linie beeinflussen, indem man den Energiefluss kappt oder verstärkt. Die Vermissian abzuschalten ist unmöglich, aber man könnte sie schwächen (oder mehr vom Heart in die Stadt Oben überquellen lassen). ‚Man‘ bedeutet in diesem Zusammenhang wahrscheinlich das OCM oder die Kirche Unserer Glorreichen Herrin."]}]}],
 regeln:null,
 figuren:[
  {id:"das-was-ueberlebt", t:"Das, was überlebt", p:104, text:[],
   namen:"Sie hatten einst Namen, aber sie erlitten einen solchen Schlag von Heart-Energie, dass die Bedeutung wie Wachs zerlief. Also: Miriamighttheshieldingfail, Johanothefacenottheface, Osricauloftheworld, Woodrowhereliesthestranglingfruit",
   besch:"Verdreht und widersprüchlich, in die Realität hinein- und aus ihr herausfließend; Qualvolle Gesichter, die um Erlösung von der Pein flehen; Alles ist flüssig, alles ist heimtückisch, ihre Worte und ihre Berührung und ihre Gedanken infizieren jene, die ihnen ausgesetzt sind.",
   motiv:"Raus hier, bevor die Druckwelle kommt, wir müssen hier raus, bevor die Druckwelle kommt, sie kommt für uns.",
   schw:"Gefährlich", res:"20", schutz:"3",
   ressourcen:"Trophäen der Vermissian (W8 Cursed)", ausr:"Gequälte Gliedmaßen, die nach Trost greifen (Kill W10, verursacht Echo-Stress)",
   besonders:null, dom:["Technology","Cursed"],
   fallout:[
    {t:"Attunement", r:"Echo", s:"leicht", x:"Deine Haut kribbelt, während du zwangsweise auf die Vermissian eingestimmt wirst. Immer wenn du das Vermissian-Netz bereist, besteht die Chance (nach Gutdünken der SL), dass du für einige Minuten verschwindest und an einem zufälligen und meist gefährlichen Ort im Netz auftauchst. [Anhaltend]"},
    {t:"Invaded", r:"Echo", s:"leicht", x:"Deine Vergangenheit ist nun mit der eines längst (fast) toten Vermissian-Technikers verstrickt. Schreibe die Geschichte deines Charakters so um, dass sie die Anwesenheit eines mörderischen, schreienden Cyber-Ghuls in vielen Ereignissen deines Lebens enthält. Er hat im Lauf der Jahre mindestens W6 dir nahestehende Menschen ermordet. [Sofort]"}]}]},

{id:"hotel-amaranthine", t:"Das Hotel Amaranthine", p:104, tiefe:3, dom:["Haven. Na ja. Irgendwie. Oder wirklich schickes Desolate."], stress:"W6", haunts:["Exquisite Canapés und kostenlose Weinbar (W4 Supplies)"],
 text:[
  "**Wake:** Die Delving Machine bricht durch das Hotel und tötet alle. Wenig später formieren sie sich neu, und aus ihrer Sicht war es einer dieser peinlichen Momente auf einer Party, in denen alle gleichzeitig verstummen.",
  "In irgendeinem vergessenen Archiv liegt ein Dokument mit dem Titel VERMISSIAN-SICHERHEITSPROTOKOLLE, und es ist vielleicht zwei Seiten lang. Daneben liegt ein weiterer Ordner mit der Aufschrift VERMISSIAN-STARTFEIERLICHKEITEN, und er ist dick genug, um einen Gutterkin zu erschlagen. Der Start der Vermissian-Linie sollte die großartigste Feier in der Spire sein, seit die Aelfir die Stadt erobert hatten. Natürlich hat sie nie stattgefunden.",
  "Aber hier unten schon. Für immer. Das Hotel Amaranthine war ein Luxushotel, errichtet neben Tintagel Junction, einer der Vermissian-Stationen der exklusiven Loft-Linie. Es war für Diplomaten und Würdenträger zu Besuch aus dem Norden gedacht und wurde ihrem Komfort angepasst. Magische Kühlsysteme halten den Ort nahe dem Gefrierpunkt, und das glitzernde Eis hebt die Schönheit der Kunstwerke an jeder Wand subtil hervor. Das Hotel öffnete nie – es wurde vom OCM geschlossen und ist als abgerissen verzeichnet, da es durch Tunnel direkt mit dem Bahnhof verbunden war, die mit Heart-Energie überflutet wurden.",
  "Der größte Teil des Hotels ist leer, ein endloses Labyrinth verlassener, verrottender Schlafzimmer und Flure. Mutierte Ratten nisten in Seidenlaken, und die Erinnerung an Regenwasser aus der Stadt Oben lässt freskengeschmückte Wände ausbeulen und bröckeln. Aber folgt man den Klängen von Musik und Gelächter hinab zum Großen Ballsaal, findet man die Party in ewig vollem Gange. Maskierte Aelfir tanzen mit würdevoller Anmut, begleitet von exquisiter Musik, Kellner machen mit Tabletts der feinsten Delikatessen der Spire die Runde, Jongleure und Akrobaten tollen für immer umher. Die nackten Diener, tätowiert mit den Uniformen von Vermissian-Ingenieuren und -Schaffnern, sind ein wenig beunruhigend, aber nicht so sehr wie die Diener, die chirurgisch so verändert wurden, dass sie humanoiden Zügen ähneln, und gezwungen sind, ewig Huckepack-Ritte zu geben.",
  "Die Gästeliste der Party wurde vor mehr als einem Jahrhundert geschrieben und war ein Who’s Who der maskierten Elite. Sie sind alle hier – in der Stadt Oben träumten sie von dem versprochenen Ball, und hier wurden diese Träume eingefangen und in Fleisch gekleidet. Viele der Aelfir-Gäste sind inzwischen gestorben, und fast alle sind in den vergangenen Jahren gealtert, sodass das Abnehmen etwa der Maske einer jungen Gesellschaftsdame ein altes Gesicht oder einen wurmigen Schädel enthüllen könnte. Es gibt auch ungebetene Gäste – Leute aus der Stadt Oben, die sich hineingeträumt haben, oder Reisende im Heart, die zu lange hier gerastet haben.",
  "Die Party ist nicht ganz ungefährlich – wenige Dinge in der Spire sind so schneidend wie die gehobene Augenbraue eines Aelfir-Maître d’, die den Rand seiner Maske überschreitet –, aber sie ist relativ frei von wütenden Ungeheuern. Die Hauptgefahr besteht darin, sich im Wirbel von Frohsinn und Ausschweifung zu verlieren: Zeit auf der Party zu verbringen verursacht **Fortune**-Stress.",
  {t:"kasten", h:"Fallout: Awkward Liaison", b:["[Fortune, leicht] Der Wein war ein bisschen zu stark, und du hast eine indiskrete Liaison mit einem Aelfir-Gast. Dein Charakter verpasst die nächsten paar Minuten des Spiels, während du abgelenkt bist. [Sofort]"]},
  {t:"kasten", h:"Fallout: Bewitched by the Party", b:["[Fortune, schwer] Die Nacht ist jung, und diese Party ist ewig. Du willst nicht gehen – deine Gefährten müssen dich hinausschleifen. [Sofort]"]}],
 ressourcen:["Die feinste Aelfir-Kleidung und -Masken (ein Jahrhundert aus der Mode, zugegeben, aber Retro ist dieses Jahr so angesagt, Darling) (W8 Haven)"],
 plots:[
  "Während die meisten Aelfir-Gäste dieser hundert Jahre alten Party in der Zwischenzeit gestorben sind, sitzt in einer Ecke des Ballsaals eine Gruppe Kinder, unterhalten von einem außergewöhnlich gruseligen Puppenspiel des **Centipede Orison**, eines einst beliebten Clowns. Freunde dich mit diesen Kindern auf der Traum-Party an, und vielleicht werden ihre heutigen Inkarnationen dir unbewusst wohlgesonnen sein.",
  "Es gibt einen Gast auf der Party, der weiß, dass alles ein Traum ist, und trotzdem freiwillig herkommt. Aramos Brightness-Sears-The-Eye besucht diesen Ort jede Nacht in seinen Träumen, diese Gedenkfeier seines großen Sieges, die bitter und ruiniert wurde. Er ist sich auch im Traum bewusst – sein jugendlicher Traum-Avatar kann das Hotel nicht verlassen, aber er kann die Delver beobachten und auf der Party mit ihnen sprechen.",
  "Das echte Hotel Amaranthine existiert noch oben in der Spire (S. 15), und wenn die Bedingungen stimmen, überlappen sich die beiden Orte und erlauben Reisen von einem zum anderen. Aramos nutzt das als Hintertür ins Heart. Die beiden Versionen des Hotels richten sich aus, wenn sich die Energieflüsse der Pulse- und der Spiral-Linie kreuzen; diese Ausrichtung lässt sich durch Überwachung der Energieflüsse vorhersagen (**Discern+Technology**). Sie geschieht natürlich alle paar Tage, kann aber künstlich ausgelöst werden, indem man Züge umherbewegt. Ein paar Passagiere verschwinden, die Energieströme beschleunigen sich, und die Tür öffnet sich. Optional sind die beiden Versionen des Hotels ausgerichtet, wenn die Charaktere es besuchen, und die Delver könnten versehentlich in die Stadt Oben reisen, ohne es zu merken. Ein Geheimgang verbindet das Hotel in der oberen Spire mit Aramos’ Villa (S. 128), sodass die Charaktere ihren Weg in Aramos’ Versteck finden könnten.",
  "Von hier aus gibt es zwei mögliche Verbindungen zur Elseworld Frozen Spire (S. 113). Erstens: Die Charaktere könnten so von der Party bezaubert sein, dass sie hinaus in eine Realität wandern, die die Feier rechtfertigt. Zweitens: Dringen sie durch den Geheimgang in Aramos’ Reich ein, könnte er auf dem Rückweg absichtlich die Verbindung zwischen den beiden Hotels stören und die Delver in der Frozen Spire abladen."],
 regeln:null, unter:[], figuren:[]}
);
K.delves.push(
{id:"d-arch-aetherstorm", t:"Der Arch of Gwynn-Ardasi zum Aetherstorm", p:99, von:"arch-gwynn-ardasi", nach:"aetherstorm", tiefe:3, dom:"Technology", stress:"W8", res:14,
 besch:"Eine gefährliche Überquerung der Berge, in denen auch der Himmel aus Bergen besteht; Alte Eisenbahntunnel und Brücken über zunehmend absurde Abgründe; Wachsende Winde drohen Reisende in den Untergang zu schleudern; Unterirdische Yeti lauern in Eisenbahntunneln.",
 erg:[
  "Ein verlassener Vermissian-Zug entpuppt sich als ein Wurm, der einen Zug als Rüstung trägt.",
  "Die schwankende Seilbrücke aus verknoteten Stromkabeln steht unter Spannung.",
  "Ein Vermissian Knight versperrt die Passage und warnt vor Gefahren voraus.",
  "Ein Aetherstorm peitscht die Bergflanke mit Blitzen.",
  "Ein freundlicher Bergtrapper bietet Tee, Mitgefühl und Kannibalismus an.",
  "Der Marsch wird unmöglich mühsam und bedroht die Vorräte."],
 verb:null, express:false},
{id:"d-aetherstorm-operations-centre", t:"Der Aetherstorm zum Vermissian Operations Centre", p:101, von:"aetherstorm", nach:"vermissian-operations-centre", tiefe:3, dom:"Cursed", stress:"W8", res:12,
 besch:"Rasch einstürzende Tunnel, der Fels löst sich mit jedem Schritt in brodelndes Heartsblood auf; Zerschmetterte Schutzschilde, von gigantischen Klauen zerrissen; Schreiende Geister, vom Wind erfasst; Überreste der letzten verzweifelten Verteidigung der Vermissian vor ihrem Zusammenbruch.",
 erg:[
  "Gnollische Forscher versuchten und scheiterten daran, das Operations Centre zu erreichen. Nun sind sie tot, und zornige Dschinn surren um ihre Leichen.",
  "Ein Alarm schrillt misstönend in der Ferne und warnt vor dem bevorstehenden Zusammenbruch des Netzes. Hört zu, und ihr hört die geheimen unterschwelligen Botschaften.",
  "Eine prekäre Brücke über die Leere, schwankend im heulenden Wind – und als die Charaktere das ferne Ende erreichen, sehen sie das überirdische Glühen von Strahlung.",
  "Rätselhafte insektoide Mönche reisen hierher, um an der Schwelle des heiligen Ortes zu sterben. Haufen spröder Kadaver versperren den Weg.",
  "Geisterzüge rasen durch den Tunnel. Sie sind völlig unstofflich, können aber dennoch die Seele eines Reisenden zu Brei zermalmen.",
  "Donner kracht im Aetherstorm und wirft die Charaktere in der Zeit aus der Bahn. Sie erhaschen einen Blick auf das Operations Centre, wie es in den Minuten vor dem Vermissian-Zwischenfall war."],
 verb:"Räume einen Weg frei, indem du den Geist eines unruhigen (tatsächlich sehr lauten) Geisterzugs austreibst oder zur Ruhe bettest.", express:false},
{id:"d-hotel-amaranthine-martyrs-close", t:"Hotel Amaranthine zu Martyr’s Close", p:106, von:"hotel-amaranthine", nach:"martyrs-close", tiefe:3, dom:"Desolate", stress:"W6", res:12,
 besch:"Die Korridore des Hotels werden rauer und unfertiger, bis sie natürliche Höhlengänge oder durch das Fleisch des Heart geschlagene Pfade sind; Radierungen und Gemälde bedeutender Aelfir an den Wänden des Hotels weichen Bildern des Delvers, der Martyr’s Close erschuf; der Geruch von Weihrauch, das Geräusch von Weinen, die Wände tropfen Tränen, und stellenweise hängen kleine salzige Stalaktiten von der Decke",
 erg:[
  "Der Klang einer Aelfir-Party – oder -Orgie – verfolgt die Reisenden. Sie hören die Feiernden, können sie aber nicht finden. Sie sind immer im nächsten Raum oder auf der anderen Seite der Wand. Es reicht aus, um W4 **Mind**-Stress zu verursachen.",
  "Hier geraten die Dimensionen aus den Fugen. Die Hotelkorridore schwellen an – oder die Delver schrumpfen. Die Delver müssen gewöhnliche Hindernisse wie eine geschlossene Tür oder ein Treppenhaus proportional mausgroß bewältigen.",
  "Die wilden, inzüchtigen Nachkommen von Partygästen haben sich über Generationen von übrig gebliebenen Canapés ernährt, während sie durch die endlosen Windungen des Hotels streiften. Nun haben sie Fleisch gewittert.",
  "Der Charakter, der Martyr’s Close erschaffen hat, wird von verwirrenden falschen Erinnerungen an sein künftiges Opfer heimgesucht. Das ist W6 Echo-Stress wert, nur für diesen Charakter.",
  "Kollateralschäden aus den Todeszuckungen des Martyr brechen durch den Gang. Gestalte diese Gefahr um den Martyr herum – ist der Martyr ein Hound, sind es Querschläger und Gewehrfeuer. Ist er eine Witch, seltsame Magie und Blut.",
  "Die Delver müssen eine steile, unebene Klippe überwinden, um aus einem dunklen Schlund zu klettern. Beim Klettern bemerken sie, dass die ‚Klippe‘ tatsächlich ein behauenes Monument ist, beschädigt von Zeit und Vernachlässigung. Erst als sie oben zurückblicken, sehen sie, dass es eine Statue des Martyr ist."],
 verb:"Halte eine Trauerrede auf den gefallenen Martyr.", express:false}
);
})(HT_DAGGER.kap["5"]);
